const escape=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export const journeyIntents=Object.freeze([
 {id:'formacao',label:'Organizar minha formação',kicker:'Clareza para o presente',title:'O que você já viveu também aponta caminhos.',body:'Reúna experiências, reconheça prioridades e dê contexto ao seu próximo passo.',actions:[
  {title:'Escolha o que pede atenção hoje.',body:'Comece por uma prioridade que caiba na sua rotina. Hoje é o ponto de partida para olhar o presente.'},
  {title:'Dê contexto às suas experiências.',body:'Em Trajetória, a Visão e o Currículo Studio ajudam a organizar o que você já construiu.'},
  {title:'Transforme uma lacuna em ação.',body:'Identifique o que quer desenvolver e escolha um passo possível. Revise a direção quando seu contexto mudar.'}
 ],links:[{label:'Conhecer Hoje',href:'/modulos/hoje/'},{label:'Explorar Trajetória',href:'/modulos/trajetoria/'}]},
 {id:'pesquisa',label:'Começar uma pesquisa',kicker:'Método para investigar',title:'Uma boa pergunta merece um caminho claro.',body:'Pesquisa organiza 15 etapas em quatro movimentos: Entender, Aplicar, Validar e Entregar.',actions:[
  {title:'Delimite a sua pergunta.',body:'Descreva o que você quer investigar e por que isso importa, antes de escolher como fazer.'},
  {title:'Prepare método e fontes.',body:'Conecte a pergunta a um desenho de trabalho. Alinhe decisões e responsabilidades com sua orientação.'},
  {title:'Revise antes de avançar.',body:'Validar e Entregar ajudam a dar atenção à consistência, aos limites e à comunicação do trabalho.'}
 ],links:[{label:'Conhecer Pesquisa',href:'/modulos/pesquisa/'},{label:'Explorar Trajetória',href:'/modulos/trajetoria/'}]},
 {id:'oportunidades',label:'Encontrar oportunidades',kicker:'Critério para escolher',title:'Amplie o horizonte. Investigue com critério.',body:'Explorar abre caminhos para a busca. Internacional, em Trajetória, dá contexto às possibilidades além do Brasil.',actions:[
  {title:'Defina o que você busca.',body:'Tema, lugar e momento da formação: escolha critérios antes de comparar possibilidades.'},
  {title:'Compare além do nome.',body:'Observe escopo, preparação e duração. Pergunte como a experiência conversa com o caminho que deseja construir.'},
  {title:'Confirme na fonte oficial.',body:'Consulte requisitos, prazos e condições diretamente com a instituição. Uma possibilidade não é uma garantia de vaga ou elegibilidade.'}
 ],links:[{label:'Conhecer Explorar',href:'/modulos/explorar/'},{label:'Ver Internacional em Trajetória',href:'/modulos/trajetoria/'}]}
].map(intent=>Object.freeze({...intent,actions:Object.freeze(intent.actions.map(Object.freeze)),links:Object.freeze(intent.links.map(Object.freeze))})));

/** Complete editorial content is rendered before JavaScript; tabs are optional. */
export function renderJourneyGuide({star='',arrow=''}={}){
 const mark=arrow||'<span aria-hidden="true">↗</span>';
 return `<section id="team" class="journey-guide" data-journey-guide aria-labelledby="journey-guide-title"><header class="journey-guide-heading"><p class="journey-guide-eyebrow">${star}<span>UM PASSO POSSÍVEL</span></p><div class="journey-guide-intro"><h2 id="journey-guide-title">Qual é o seu<br><i>próximo passo?</i></h2><p>Você não precisa resolver tudo agora.<br>Comece pelo que faz sentido para você.</p></div></header><div class="journey-guide-tabs" data-journey-tabs aria-label="Escolha o seu próximo passo" hidden>${journeyIntents.map((intent,i)=>`<button type="button" id="journey-tab-${intent.id}" data-journey-tab="${intent.id}" aria-controls="journey-panel-${intent.id}"><span class="journey-guide-tab-number" aria-hidden="true">0${i+1}</span><span>${escape(intent.label)}</span><span class="journey-guide-tab-arrow" aria-hidden="true">↗</span></button>`).join('')}</div><div class="journey-guide-panels">${journeyIntents.map((intent,i)=>`<article class="journey-guide-panel" id="journey-panel-${intent.id}" data-journey-panel="${intent.id}" aria-labelledby="journey-intent-${intent.id}"><div class="journey-guide-context"><p class="journey-guide-panel-kicker">0${i+1} <span aria-hidden="true">/</span> ${escape(intent.kicker)}</p><p class="journey-guide-intent-label" id="journey-intent-${intent.id}">${escape(intent.label)}</p><h3>${escape(intent.title)}</h3><p class="journey-guide-body">${escape(intent.body)}</p></div><ol class="journey-guide-actions" aria-label="Três ações para ${escape(intent.label.toLowerCase())}">${intent.actions.map((action,index)=>`<li><span class="journey-guide-action-number" aria-hidden="true">0${index+1}</span><div><h4>${escape(action.title)}</h4><p>${escape(action.body)}</p></div></li>`).join('')}</ol><nav class="journey-guide-links" aria-label="Módulos para ${escape(intent.label.toLowerCase())}">${intent.links.map(link=>`<a href="${escape(link.href)}"><span>${escape(link.label)}</span>${mark}</a>`).join('')}</nav></article>`).join('')}</div><p class="journey-guide-note"><span>Em pré-lançamento.</span> Explore os módulos. Sua escolha nesta página não é salva nem enviada.</p></section>`;
}
